  const GREET = {"א":["gm_alef",2.3],"ב":["gm_bet",2.8],"ג":["gm_gimel",3],"ד":["gm_dalet",2.3],"ה":["gm_he",2.3],"ו":["gm_vav",2.8],"ז":["gm_zayin",3],"ח":["gm_het",2.2],"ט":["gm_tet",2.3],"י":["gm_yod",2.8],"כ":["gm_kaf",3],"ל":["gm_lamed",2.2],"מ":["gm_mem",2.3],"נ":["gm_nun",2.8],"ס":["gm_samekh",3],"ע":["gm_ayin",2.2],"פ":["gm_pe",2.3],"צ":["gm_tsadi",2.8],"ק":["gm_qof",3],"ר":["gm_resh",2.2],"ש":["gm_shin",2.3],"ת":["gm_tav",2.8],"ך":["gm_fin_kaf",3],"ם":["gm_fin_mem",2.2],"ן":["gm_fin_nun",2.3],"ף":["gm_fin_pe",2.8],"ץ":["gm_fin_tsadi",3]};   // the clip, and when it is said (s after the touch, as the letter smiles)
  let ctx = null, noise = null;
  function audio() {   // Web Audio, made on the first touch (browsers allow sound only after one)
    if (!ctx) { const A = window.AudioContext || window.webkitAudioContext; if (!A) return null; ctx = new A();
      noise = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate); const d = noise.getChannelData(0); let b = 0;
      for (let i = 0; i < d.length; i++) { b = 0.97 * b + 0.03 * (Math.random() * 2 - 1); d[i] = b * 6; } }   // soft, airy noise
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  }
  function puff(t, len, f, peak, rise) {   // one breath of air: a filtered noise that swells and fades
    const s = ctx.createBufferSource(); s.buffer = noise; s.loop = true;
    const flt = ctx.createBiquadFilter(); flt.type = "bandpass"; flt.frequency.value = f; flt.Q.value = 0.7;
    const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(peak, t + len * rise); g.gain.exponentialRampToValueAtTime(0.0001, t + len);
    s.connect(flt).connect(g).connect(ctx.destination); s.start(t); s.stop(t + len + 0.05);
  }
  function hush(t, len, f0, f1, peak) {   // a soft breath: muffled noise (low-pass, its brightness drifting f0 -> f1) that swells and fades on a smooth curve, no edges
    const s = ctx.createBufferSource(); s.buffer = noise; s.loop = true;
    const flt = ctx.createBiquadFilter(); flt.type = "lowpass"; flt.Q.value = 0.3; flt.frequency.setValueAtTime(f0, t); flt.frequency.linearRampToValueAtTime(f1, t + len);
    const n = 64, c = new Float32Array(n); for (let i = 0; i < n; i++) c[i] = peak * Math.pow(Math.sin(Math.PI * i / (n - 1)), 2) + 0.00001;
    const g = ctx.createGain(); g.gain.value = 0.00001; g.gain.setValueCurveAtTime(c, t, len);
    s.connect(flt).connect(g).connect(ctx.destination); s.start(t); s.stop(t + len + 0.05);
  }
  function breath(t, T) {
    if (window.LETTERS_ANIMATED.breath === "soft") { hush(t + 0.1, T * 0.45, 380, 620, 0.05); hush(t + T * 0.5, T * 0.48, 520, 260, 0.06); return; }   // gentle: a quiet, muffled breath in and out
    puff(t + 0.05, T * 0.43, 900, 0.10, 0.8); puff(t + T * 0.5, T * 0.45, 450, 0.16, 0.2);   // deep: a deep breath in as it rises, a long breath out as it settles
  }
  window.LETTERS_ANIMATED = {
    letters: Object.keys(art),
    audioBase: "audio/",   // where gm_<name>.mp3 are; missing clips stay silent (never a browser voice)
    sound: true,           // false: no breathing and no greeting
    breath: "soft",        // the sleeping breath: "soft" (gentle, chosen by Golan 20.10) or "deep" (the first one)
    make(letter) {
      if (!art[letter]) return null;
      if (!document.getElementById("la-style")) { const s = document.createElement("style"); s.id = "la-style"; s.textContent = css; document.head.appendChild(s); }
      const box = document.createElement("div");
      box.innerHTML = '<svg class="la" style="' + art[letter][0] + '" viewBox="0 0 1000 1000" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="' + letter + '">' + art[letter][1] + "</svg>";
      const el = box.firstChild, L = window.LETTERS_ANIMATED; let timer = null, greet = null;
      const body = el.querySelector(".body"), T = parseFloat(el.style.getPropertyValue("--bd"));
      const stopBreath = () => { clearInterval(timer); timer = null; };
      // breathing sound in step with the motion: restart the motion and the sound together
      el.breathe = () => { stopBreath(); if (!L.sound || !audio() || el.classList.contains("la-wake")) return;
        body.style.animation = "none"; void body.getBoundingClientRect(); body.style.animation = "";
        breath(ctx.currentTime, T); timer = setInterval(() => { if (!el.isConnected) return stopBreath(); breath(ctx.currentTime, T); }, T * 1000); };
      el.wake = () => { stopBreath(); clearTimeout(greet); el.classList.remove("la-wake"); void el.getBoundingClientRect(); el.classList.add("la-wake");
        if (L.sound && audio()) greet = setTimeout(() => { const a = new Audio(L.audioBase + GREET[letter][0] + ".mp3"); a.play().catch(() => {}); }, GREET[letter][1] * 1000); };
      el.sleep = () => { clearTimeout(greet); el.classList.remove("la-wake"); el.breathe(); };
      el.wakeTime = parseFloat(el.style.getPropertyValue("--dur"));   // s until it is fully awake
      return el;
    },
  };
